import { TestingModule } from '@nestjs/testing';
import { MikroORM } from '@mikro-orm/core';
import { createIntegrationTestModule, cleanDatabase } from './setup';
import { InventoryReservation } from '../../src/entities/inventory-reservation.entity';
import { buildInventoryReservation } from '../factories/inventory-reservation.factory';
import { Category } from '../../src/entities/category.entity';
import { buildCategory } from '../factories/category.factory';
import { Product } from '../../src/entities/product.entity';
import { buildProduct } from '../factories/product.factory';

describe('InventoryReservation Relationships', () => {
  let module: TestingModule;
  let orm: MikroORM;
  let categoryId: string;
  let productId: string;

  beforeAll(async () => {
    module = await createIntegrationTestModule();
    orm = module.get(MikroORM);
  });

  beforeEach(async () => {
    const em = orm.em.fork();
    const categoryEntity = em.create(
      Category,
      buildCategory(),
    );
    await em.persistAndFlush(categoryEntity);
    categoryId = categoryEntity.id;
    const productEntity = em.create(
      Product,
      buildProduct({ category: categoryId }),
    );
    await em.persistAndFlush(productEntity);
    productId = productEntity.id;
  });

  afterEach(async () => {
    await cleanDatabase(orm);
  });

  afterAll(async () => {
    await module.close();
  });

  describe('belongs_to Product', () => {
    it('persists product reference', async () => {
      const em = orm.em.fork();
      const data = buildInventoryReservation({ product: productId });
      const saved = em.create(InventoryReservation, data);
      await em.persistAndFlush(saved);
      await em.populate(saved, ['product']);
      expect(saved.product.id).toBe(productId);
    });

    it('loads parent via relation', async () => {
      const em = orm.em.fork();
      const data = buildInventoryReservation({ product: productId });
      const saved = em.create(InventoryReservation, data);
      await em.persistAndFlush(saved);
      const loaded = await em.findOne(
        InventoryReservation,
        { id: saved.id },
        { populate: ['product'] },
      );
      expect(loaded).not.toBeNull();
      expect(loaded!.product).toBeDefined();
      expect(loaded!.product.id).toBe(productId);
    });

    it('rejects entity without required product', async () => {
      const em = orm.em.fork();
      const data = buildInventoryReservation({ product: undefined as unknown as string });
      const row = em.create(InventoryReservation, data);
      await expect(em.persistAndFlush(row)).rejects.toThrow();
    });
  });
});
